class Solution {
public:
    vector<vector<string>> partition(string s) {
        int n = s.size();
        vector<vector<bool>> ok(n, vector<bool>(n, false));
        for (int i = n - 1; i >= 0; i--)
            for (int j = i; j < n; j++)
                ok[i][j] = s[i] == s[j] && (j - i < 2 || ok[i + 1][j - 1]);
        vector<vector<string>> res;
        vector<string> path;
        dfs(s, ok, 0, path, res);
        return res;
    }
private:
    void dfs(const string& s, vector<vector<bool>>& ok, int start,
             vector<string>& path, vector<vector<string>>& res) {
        if (start == (int)s.size()) {
            res.push_back(path);
            return;
        }
        for (int end = start; end < (int)s.size(); end++) {
            if (!ok[start][end]) continue;
            path.push_back(s.substr(start, end - start + 1));
            dfs(s, ok, end + 1, path, res);
            path.pop_back();
        }
    }
};

