class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        vector<int>* pa = &nums1;
        vector<int>* pb = &nums2;
        if (pa->size() > pb->size()) swap(pa, pb);
        vector<int>& a = *pa;
        vector<int>& b = *pb;
        int m = a.size(), n = b.size();
        int half = (m + n + 1) / 2;
        const long long NEG = LLONG_MIN / 4, POS = LLONG_MAX / 4;
        int l = 0, r = m;
        while (l <= r) {
            int i = (l + r) / 2, j = half - i;
            long long la = i > 0 ? a[i - 1] : NEG;
            long long ra = i < m ? a[i] : POS;
            long long lb = j > 0 ? b[j - 1] : NEG;
            long long rb = j < n ? b[j] : POS;
            if (la <= rb && lb <= ra) {
                if ((m + n) % 2) return (double)max(la, lb);
                return (max(la, lb) + min(ra, rb)) / 2.0;
            }
            if (la > rb) r = i - 1;
            else l = i + 1;
        }
        return 0.0;
    }
};

