class Solution {
public:
    string decodeString(string s) {
        vector<pair<string, int>> stack;
        string cur;
        int k = 0;
        for (char ch : s) {
            if (ch >= '0' && ch <= '9') {
                k = k * 10 + (ch - '0');
            } else if (ch == '[') {
                stack.push_back(make_pair(cur, k));
                cur.clear();
                k = 0;
            } else if (ch == ']') {
                string prev = stack.back().first;
                int num = stack.back().second;
                stack.pop_back();
                string rep;
                for (int i = 0; i < num; i++) rep += cur;
                cur = prev + rep;
            } else {
                cur += ch;
            }
        }
        return cur;
    }
};

