class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        int n = nums.size();
        int target = n - k;
        int lo = 0, hi = n - 1;
        while (true) {
            int pivot = nums[(lo + hi) / 2];
            int lt = lo, i = lo, gt = hi;
            while (i <= gt) {
                if (nums[i] < pivot) {
                    swap(nums[lt], nums[i]);
                    lt++;
                    i++;
                } else if (nums[i] > pivot) {
                    swap(nums[i], nums[gt]);
                    gt--;
                } else {
                    i++;
                }
            }
            if (target < lt) hi = lt - 1;
            else if (target > gt) lo = gt + 1;
            else return nums[target];
        }
    }
};

